/bin/zsh -c "python3 - <<'PY'
from pathlib import Path
p = Path(\"seating-trial.html\")
s = p.read_text()
s = s.replace('font-size: clamp(2rem, 6vw, 2.65rem);', 'font-size: 2.65rem;')
start = s.index('  .comparison {')
end = s.index('  .method', start)
s = s[:start] + '''  .comparison { width: 100%; border-collapse: collapse; table-layout: fixed; margin-top: 8px; }
  .comparison .area-column { width: 112px; }
  .comparison .occupancy-column { width: 120px; }
  .comparison .full-column { width: 90px; }
  .comparison th, .comparison td { padding: 0 0 0 12px; }
  .comparison th:first-child { padding-left: 0; text-align: left; }
  .comparison thead th { font-size: 0.72rem; }
  .comparison tbody th, .comparison tbody td {
    height: 38px;
    border-bottom: 1px solid #d2d2d2;
    font-size: 0.82rem;
  }
  .zone small { font-weight: 400; font-size: inherit; }
  .number { text-align: right; font-variant-numeric: tabular-nums; }
  .track { display: block; height: 12px; border: 1px solid #666; }
  .fill { display: block; height: 100%; background: #646464; }
  .window .fill { background: #181818; }
  .axis { font-size: 0.7rem; font-weight: 400; text-align: left; }
  .axis span:last-child { float: right; }
''' + s[end:]
start = s.index('  table {')
end = s.index('  .pair-start', start)
s = s[:start] + '''  .observations { width: 100%; min-width: 410px; border-collapse: collapse; table-layout: fixed; font-size: 0.83rem; }
  .observations th, .observations td { text-align: center; padding: 6px 2px; }
  .observations thead tr:first-child th { border-top: 1px solid #242424; border-bottom: 1px solid #c6c6c6; }
  .observations thead tr:last-child th, .observations thead th[rowspan] { border-bottom: 1px solid #242424; }
  .observations thead tr:last-child th { font-size: 0.72rem; font-weight: 400; }
  .observations tbody tr { border-bottom: 1px solid #c6c6c6; }
  .observations tbody th, .observations thead th[rowspan] { text-align: left; padding-left: 6px; }
''' + s[end:]
s = s.replace('    .comparison > div { grid-template-columns: 76px minmax(30px, 1fr) 77px 56px; column-gap: 6px; }\\n    .comparison .row { font-size: 0.74rem; }', '''    h1 { font-size: 2rem; }
    .comparison .area-column { width: 76px; }
    .comparison .occupancy-column { width: 77px; }
    .comparison .full-column { width: 56px; }
    .comparison th, .comparison td { padding-left: 6px; }
    .comparison tbody th, .comparison tbody td { font-size: 0.74rem; }''')
start = s.index('    <div class=\"comparison\"')
end = s.index('    <p class=\"method\"', start)
s = s[:start] + '''    <table class=\"comparison\" aria-label=\"Occupancy and full observations by seating area\">
      <colgroup>
        <col class=\"area-column\"><col><col class=\"occupancy-column\"><col class=\"full-column\">
      </colgroup>
      <thead>
        <tr>
          <th scope=\"col\">Area / capacity</th>
          <th class=\"axis\" scope=\"col\" aria-label=\"Occupancy scale from 0 to 100 percent\"><span>0%</span><span>100%</span></th>
          <th class=\"number\" scope=\"col\">Occupancy</th>
          <th class=\"number\" scope=\"col\">Times full</th>
        </tr>
      </thead>
      <tbody>
        <tr class=\"window\">
          <th class=\"zone\" scope=\"row\">Window <small>6 seats</small></th>
          <td><span class=\"track\" aria-hidden=\"true\"><span class=\"fill\" style=\"width: 95.833333%\"></span></span></td>
          <td class=\"number\"><span>46/48</span> <strong>95.8%</strong></td>
          <td class=\"number\"><strong>6/8</strong></td>
        </tr>
        <tr>
          <th class=\"zone\" scope=\"row\">Group <small>8 seats</small></th>
          <td><span class=\"track\" aria-hidden=\"true\"><span class=\"fill\" style=\"width: 89.0625%\"></span></span></td>
          <td class=\"number\"><span>57/64</span> <strong>89.1%</strong></td>
          <td class=\"number\"><strong>4/8</strong></td>
        </tr>
        <tr>
          <th class=\"zone\" scope=\"row\">Quiet <small>12 seats</small></th>
          <td><span class=\"track\" aria-hidden=\"true\"><span class=\"fill\" style=\"width: 88.541667%\"></span></span></td>
          <td class=\"number\"><span>85/96</span> <strong>88.5%</strong></td>
          <td class=\"number\"><strong>3/8</strong></td>
        </tr>
      </tbody>
    </table>
''' + s[end:]
s = s.replace('<table aria-labelledby=\"observations\"', '<table class=\"observations\" aria-labelledby=\"observations\"')
s = s.replace('Quiet seats had the highest headcounts. As a share of capacity, window seats were used most.', 'Quiet had the most occupied seats at every check. Window had the highest occupancy as a share of capacity.')
s = s.replace('The historical counts show how often seating was full, while the separate tally helps gauge unmet demand.', 'The historical counts capture seat use only.')
p.write_text(s)
PY
wkhtmltopdf --quiet --grayscale --disable-javascript --print-media-type --disable-smart-shrinking --page-size Letter --margin-top 0.48in --margin-bottom 0.48in --margin-left 0.52in --margin-right 0.52in seating-trial.html /tmp/seating-wk-test.pdf
pdfinfo /tmp/seating-wk-test.pdf
pdftoppm -gray -r 105 -singlefile /tmp/seating-wk-test.pdf /tmp/seating-preview
magick /tmp/seating-preview.pgm /tmp/seating-preview.png
pdftk /tmp/seating-wk-test.pdf dump_data"
